def _t2_resources(directory: Path, command_id: str, argv: list[str], process_pid: int | None) -> dict:
    from collections import Counter

    expected = [arg for arg in argv if "::" in arg]
    records, errors, nodes = [], [], Counter()
    counts = Counter()
    scenario_caps = {
        "test_memory_sqlite_publication_wait_requires_current_d": 2,
        "test_dual_database_order_and_partial_commit": 6,
        "test_original_budget_debit_not_refilled_by_retry": 2,
        "test_b_local_writer_requires_private_scope": 2,
    }
    peak_active_polls = 0
    paths = sorted(directory.iterdir()) if directory.is_dir() else []
    if len(paths) > 10000:
        raise ValueError("T2 resource directory exceeds finite evidence cap")
    for path in paths:
        record = {"path": str(path), "pin": None, "data": None, "error": None}
        try:
            if path.is_symlink() or not path.is_file() or path.suffix != ".json":
                raise ValueError("exact regular T2 resource JSON required")
            record["pin"] = _t2_pin(path)
            value = read_json(path)
            record["data"] = value
            if value["schema_version"] != "bigsmall.r158-t2-resource.v1":
                raise ValueError("exact T2 resource sidecar schema required")
            if value["command_id"] != command_id or value["nodeid"] not in expected:
                raise ValueError("T2 sidecar command/node provenance differs")
            if value["pid"] != process_pid or process_pid is None:
                raise ValueError("T2 sidecar actual child PID differs")
            nodes[value["nodeid"]] += 1
            if value["entered_contract_guard"] is not True:
                raise ValueError("T2 attempt must record the contract guard")
            if command_id == "t2_green" and value["entered_behavior"] is not True:
                raise ValueError("T2 GREEN must enter every behavioral body")
            resources = value["resources"]
            if type(resources) is not list or type(value["allocation_attempts"]) is not int:
                raise ValueError("actual resource allocation denominator required")
            if value["allocation_attempts"] != len(resources):
                raise ValueError("resource attempts do not match actual object records")
            if value["cleanup_errors"]:
                raise ValueError("actual T2 resource cleanup errors retained")
            by_id = {}
            for resource in resources:
                key = resource["resource_id"]
                if type(key) is not int or key <= 0 or key in by_id:
                    raise ValueError("unique actual resource identities required")
                if resource["pid"] != process_pid:
                    raise ValueError("resource child identity differs")
                by_id[key] = resource
            lifecycles = value["worker_lifecycles"]
            if type(lifecycles) is not list:
                raise ValueError("actual worker lifecycle records required")
            poll_ids, linked, intervals = set(), Counter(), []
            observed_sequences, previous_start = set(), 0
            for ordinal, call in enumerate(lifecycles, 1):
                poll_id = call["poll_id"]
                if type(poll_id) is not int or poll_id != ordinal or poll_id in poll_ids:
                    raise ValueError("unique monotonic poll IDs required")
                poll_ids.add(poll_id)
                worker = by_id[call["worker_resource_id"]]
                if worker["kind"] != "worker" or poll_id not in worker["poll_ids"]:
                    raise ValueError("poll must resolve to the same actual worker")
                linked[worker["resource_id"]] += 1
                if call["attempted"] is not True:
                    raise ValueError("actual poll attempt required")
                if type(call["entered"]) is not bool or type(call["returned_normally"]) is not bool:
                    raise ValueError("strict poll entry/return observations required")
                start, end = call["start_sequence"], call["end_sequence"]
                if type(start) is not int or type(end) is not int or not 0 < start < end:
                    raise ValueError("finished poll attempt sequence required")
                if start <= previous_start or start in observed_sequences or end in observed_sequences:
                    raise ValueError("unique ordered observation sequences required")
                previous_start = start
                observed_sequences.update((start, end))
                counts["attempted_poll_lifecycles"] += 1
                if call["entered"]:
                    entry = call["entry_sequence"]
                    if type(entry) is not int or not start < entry < end:
                        raise ValueError("actual poll entry must precede its finish")
                    if entry in observed_sequences:
                        raise ValueError("poll entry sequence duplicated")
                    observed_sequences.add(entry)
                    if (type(call["thread_id"]) is not int
                            or type(call["native_thread_id"]) is not int):
                        raise ValueError("actual poll thread coordinates required")
                    counts["entered_poll_lifecycles"] += 1
                    intervals.extend(((entry, 1), (end, -1)))
                elif (call["entry_sequence"] is not None or call["thread_id"] is not None
                      or call["native_thread_id"] is not None):
                    raise ValueError("unentered poll cannot invent entry/thread observations")
                if call["returned_normally"]:
                    if (not call["entered"] or type(call["return_value"]) is not bool
                            or call["exception"] is not None):
                        raise ValueError("normal poll return must preserve actual bool and entry")
                    counts["normally_returned_poll_lifecycles"] += 1
                elif (call["return_value"] is not None or type(call["exception"]) is not dict
                      or set(call["exception"]) != {"type", "message"}
                      or any(type(item) is not str for item in call["exception"].values())):
                    raise ValueError("failed poll must preserve its actual exception")
            family = value["nodeid"].split("::")[-1].split("[")[0]
            if family not in scenario_caps or len(lifecycles) > scenario_caps[family]:
                raise ValueError("actual scenario poll lifecycle cap exceeded")
            active, local_peak = 0, 0
            for _, delta in sorted(intervals):
                active += delta
                if active < 0:
                    raise ValueError("poll interval ordering differs")
                local_peak = max(local_peak, active)
            if active != 0 or local_peak > 2:
                raise ValueError("actual concurrent poll cap exceeded or unfinished")
            peak_active_polls = max(peak_active_polls, local_peak)
            counts["allocation_attempts"] += len(resources)
            for resource in resources:
                if resource["initialization_attempted"] is not True:
                    raise ValueError("resource attempt missing")
                if type(resource["initialized"]) is not bool:
                    raise ValueError("actual resource initialization observation required")
                counts["initialized"] += int(resource["initialized"])
                counts["kind:" + resource["kind"]] += 1
                if resource["cleanup_observed"] is not True:
                    raise ValueError("resource cleanup unavailable or failed")
                if resource["kind"] == "worker":
                    counts["constructed_worker_attempts"] += 1
                    counts["initialized_workers"] += int(resource["initialized"])
                    ids = resource["poll_ids"]
                    actual_ids = [call["poll_id"] for call in lifecycles
                                  if call["worker_resource_id"] == resource["resource_id"]]
                    if (type(ids) is not list or any(type(item) is not int for item in ids)
                            or ids != actual_ids or len(ids) != linked[resource["resource_id"]]):
                        raise ValueError("worker poll associations differ")
                    if resource["final_active_job_id"] != "":
                        raise ValueError("actual worker idle state must be empty string")
                    if (type(resource["session_observed"]) is not bool
                            or type(resource["heartbeat_observed"]) is not bool):
                        raise ValueError("worker runtime allocation observation missing")
                    for key, kind, peak_key in (
                        ("broker_resource_ids", "broker_thread", "broker_peak_alive"),
                        ("heartbeat_resource_ids", "heartbeat_thread", "heartbeat_peak_alive"),
                    ):
                        thread_ids = resource[key]
                        if (type(thread_ids) is not list or len(set(thread_ids)) != len(thread_ids)
                                or type(resource[peak_key]) is not int
                                or not 0 <= resource[peak_key] <= 1):
                            raise ValueError("worker thread identity/concurrency observation differs")
                        for thread_id in thread_ids:
                            thread = by_id[thread_id]
                            if (thread["kind"] != kind
                                    or thread["worker_resource_id"] != resource["resource_id"]
                                    or thread["cleanup_observed"] is not True
                                    or thread["alive_after_join"] is not False
                                    or type(thread["thread_ident"]) is not int
                                    or type(thread["native_thread_id"]) is not int
                                    or thread["session_resource_id"] not in resource["session_resource_ids"]):
                                raise ValueError("actual worker thread link or termination differs")
                    sessions = resource["session_resource_ids"]
                    if type(sessions) is not list or len(set(sessions)) != len(sessions):
                        raise ValueError("actual session identities required")
                    for session_id in sessions:
                        session = by_id[session_id]
                        if (session["kind"] != "lease_session"
                                or session["worker_resource_id"] != resource["resource_id"]
                                or session["cleanup_observed"] is not True
                                or session["broker_alive"] is not False):
                            raise ValueError("worker session ownership/release differs")
                    if (resource["session_observed"] != bool(sessions)
                            or resource["heartbeat_observed"] != bool(resource["heartbeat_resource_ids"])):
                        raise ValueError("runtime presence and actual resource links differ")
                    if not ids:
                        if (resource["cleanup_basis"] != "never_polled_no_owned_runtime"
                                or resource["initial_active_job_id"] != ""
                                or resource["session_observed"] is not False
                                or resource["heartbeat_observed"] is not False
                                or sessions or resource["broker_resource_ids"]
                                or resource["heartbeat_resource_ids"] or resource["close_attempts"]):
                            raise ValueError("unpolled worker cannot invent runtime execution/close")
                        counts["never_polled_workers"] += 1
                    elif resource["cleanup_basis"] != "poll_finished_runtime_released":
                        raise ValueError("polled worker must preserve actual runtime cleanup basis")
                elif resource["kind"] in {"broker_thread", "heartbeat_thread"}:
                    owner = by_id[resource["worker_resource_id"]]
                    key = ("broker_resource_ids" if resource["kind"] == "broker_thread"
                           else "heartbeat_resource_ids")
                    if owner["kind"] != "worker" or resource["resource_id"] not in owner[key]:
                        raise ValueError("thread cannot omit its real owning worker")
                counts["cleanup_observed"] += 1
            if value["observations"]["observers_restored"] is not True:
                raise ValueError("T2 observer restoration not observed")
            if command_id == "t2_green" and value["observations"]["assertions_completed"] is not True:
                raise ValueError("T2 behavioral assertions did not complete")
        except (OSError, ValueError, TypeError, KeyError) as error:
            record["error"] = {"type": type(error).__name__, "message": str(error)}
            errors.append({"path": str(path), **record["error"]})
        records.append(record)
    mapping_match = nodes == Counter(expected)
    if not mapping_match:
        errors.append({"stage": "helper map", "type": "MissingOrDuplicateNode",
                       "message": "exactly one actual attempt sidecar per selected node required"})
    if counts["attempted_poll_lifecycles"] > 18 or counts["attempted_poll_lifecycles"] > 64:
        errors.append({"stage": "cap", "type": "WorkerLifecycleCap",
                       "message": "T2 attempted poll18/parent64 cap exceeded"})
    valid = not errors and mapping_match
    return {"schema_version": "bigsmall.r158-t2-resource-summary.v1",
            "command_id": command_id, "actual_node_attempts": len(records),
            "actual_node_counts": dict(nodes), "records": records,
            "counts": dict(counts), "all_records_valid": valid, "validation_errors": errors,
            "peak_active_polls_per_node": peak_active_polls,
            "interpretation": "Interface RED may reject before allocation; never behavioral proof.",
            "unobserved": {"OS_handles": None, "external_models": None, "GPU_native": None,
                           "network_calls": None}}

@contextmanager
def _b_t2_attempt(request):
    import sys

    previous_profile = sys.getprofile()
    value = {
        "schema_version": "bigsmall.r158-t2-resource.v1",
        "command_id": os.environ.get("BIGSMALL_R158_COMMAND"),
        "nodeid": request.node.nodeid, "pid": os.getpid(),
        "scenario": request.node.name, "entered_contract_guard": True,
        "entered_behavior": False, "allocation_attempts": 0, "resources": [],
        "worker_lifecycles": [],
        "cleanup_errors": [], "observations": {"assertions_completed": False,
                                              "observers_restored": False, "scenarios": []},
        "unobserved": {"OS_handles": None, "external_models": None, "GPU_native": None,
                       "network_calls": None},
    }
    try:
        yield value
        value["observations"]["assertions_completed"] = True
    finally:
        error_type, error, _ = sys.exc_info()
        value["observations"]["exit_exception"] = None if error_type is None else {
            "type": error_type.__name__, "message": str(error),
        }
        value["allocation_attempts"] = len(value["resources"])
        if not value["entered_behavior"]:
            value["observations"]["observers_restored"] = sys.getprofile() is previous_profile
        sink = os.environ.get("BIGSMALL_R158_T2_RESOURCE_DIR")
        assert sink, "T2 requires the exact ROOT-approved per-command resource sink"
        directory = Path(sink)
        assert directory.is_dir() and not directory.is_symlink()
        name = hashlib.sha256(request.node.nodeid.encode()).hexdigest() + ".json"
        with (directory / name).open("x", encoding="utf-8") as stream:
            json.dump(value, stream, ensure_ascii=False, allow_nan=False, indent=2)
            stream.write("\n")


@contextmanager
def _b_t2_observe(monkeypatch, value):
    """Observe real constructors, connections and issuer clocks; no permission mocks."""
    import sys
    import time
    from types import SimpleNamespace
    from cloud_edge_robot_arm.research.operational_time_v1 import _open_clock_for_test
    from cloud_edge_robot_arm.repositories.event_autonomy import (
        InMemoryEventAutonomyRepository, SQLiteEventAutonomyRepository,
    )
    from cloud_edge_robot_arm.simulation_runtime import operational_lease as lease_module
    from cloud_edge_robot_arm.simulation_runtime.sqlite_repository import SQLiteSimulationJobRepository
    from cloud_edge_robot_arm.simulation_runtime.worker import SimulationWorker
    from cloud_edge_robot_arm.vision import operational_windows

    guard = threading.RLock()
    objects, methods, clocks, release_events, worker_refs, session_refs = {}, {}, [], [], [], []
    sequence = 0
    poll_context = threading.local()
    real_poll = SimulationWorker.poll_once
    poll_code = real_poll.__code__
    fault = {"operation_id": None, "database": None, "phase": None, "fired": False}
    previous_profile, previous_thread_profile = sys.getprofile(), threading.getprofile()

    def tick():
        nonlocal sequence
        with guard:
            sequence += 1
            return sequence

    def add(obj, kind, **details):
        with guard:
            key = id(obj)
            if key in objects:
                return objects[key][1]
            record = {
                "resource_id": key, "kind": kind, "class_module": type(obj).__module__,
                "class_name": type(obj).__qualname__, "pid": os.getpid(),
                "creating_thread": threading.get_ident(), "creating_native_thread": threading.get_native_id(),
                "initialization_attempted": True, "initialized": False, "initialization_error": None,
                "close_attempts": [], "cleanup_observed": None, **details,
            }
            if kind == "worker":
                record.update(poll_ids=[], initial_active_job_id=None, final_active_job_id=None,
                              session_observed=None, heartbeat_observed=None, cleanup_basis=None,
                              session_resource_ids=[], broker_resource_ids=[], heartbeat_resource_ids=[],
                              broker_peak_alive=None, heartbeat_peak_alive=None)
                worker_refs.append(obj)
            objects[key] = (obj, record)
            value["resources"].append(record)
            return record

    def close_wrapper(original, kind):
        def close(obj, *args, **kwargs):
            record = add(obj, kind)
            call = {"thread": threading.get_ident(), "native_thread": threading.get_native_id(),
                    "returned": False, "error": None}
            record["close_attempts"].append(call)
            try:
                result = original(obj, *args, **kwargs)
            except BaseException as error:
                call["error"] = {"type": type(error).__name__, "message": str(error)}
                raise
            else:
                call["returned"] = True
                record["cleanup_observed"] = True
                return result
        return close

    def init_wrapper(original, kind):
        def initialize(obj, *args, **kwargs):
            record = add(obj, kind)
            try:
                result = original(obj, *args, **kwargs)
            except BaseException as error:
                record["initialization_error"] = {"type": type(error).__name__, "message": str(error)}
                if kind == "worker":
                    record["initial_active_job_id"] = getattr(obj, "active_job_id", None)
                    record["initial_state_observation"] = "constructor_exception"
                    sample_runtime(obj)
                raise
            else:
                record["initialized"] = True
                if kind == "worker":
                    record["initial_active_job_id"] = getattr(obj, "active_job_id", None)
                    record["initial_state_observation"] = "constructor_return"
                    sample_runtime(obj)
                return result
        return initialize

    def sample_runtime(worker):
        with guard:
            sample_runtime_locked(worker)

    def sample_runtime_locked(worker):
        record = objects[id(worker)][1]
        session = getattr(worker, "_operational_lease_session", None)
        heartbeat = None if session is None else getattr(session, "_heartbeat_thread", None)
        # Presence is observed separately from constructor success and from a close call.
        if hasattr(worker, "_operational_lease_session"):
            record["session_observed"] = session is not None or record["session_observed"] is True
        if hasattr(worker, "_operational_lease_session"):
            record["heartbeat_observed"] = heartbeat is not None or record["heartbeat_observed"] is True
        if session is not None:
            session_record = add(session, "lease_session")
            if id(session) not in record["session_resource_ids"]:
                record["session_resource_ids"].append(id(session))
            session_record["worker_resource_id"] = id(worker)
        for thread, kind, key, peak_key in (
            (None if session is None else getattr(session, "_broker", None),
             "broker_thread", "broker_resource_ids", "broker_peak_alive"),
            (heartbeat, "heartbeat_thread", "heartbeat_resource_ids", "heartbeat_peak_alive"),
        ):
            if thread is not None:
                thread_record = add(thread, kind)
                thread_record["initialized"] = thread.ident is not None
                thread_record["worker_resource_id"] = id(worker)
                thread_record["session_resource_id"] = None if session is None else id(session)
                if id(thread) not in record[key]:
                    record[key].append(id(thread))
            if hasattr(worker, "_operational_lease_session"):
                alive = sum(int(objects[item][0].is_alive()) for item in record[key])
                record[peak_key] = max(record[peak_key] or 0, alive)

    def poll_once(worker, *args, **kwargs):
        record = add(worker, "worker")
        with guard:
            call = {"poll_id": len(value["worker_lifecycles"]) + 1,
                    "worker_resource_id": id(worker), "attempted": True, "entered": False,
                    "returned_normally": False, "return_value": None, "exception": None,
                    "start_sequence": tick(), "entry_sequence": None, "end_sequence": None,
                    "thread_id": None, "native_thread_id": None}
            value["worker_lifecycles"].append(call)
            record["poll_ids"].append(call["poll_id"])
        previous_call = getattr(poll_context, "call", None)
        poll_context.call = call
        try:
            result = real_poll(worker, *args, **kwargs)
        except BaseException as error:
            call["exception"] = {"type": type(error).__name__, "message": str(error)}
            raise
        else:
            call["returned_normally"] = True
            call["return_value"] = result
            return result
        finally:
            sample_runtime(worker)
            call["end_sequence"] = tick()
            poll_context.call = previous_call

    def after_commit(conn, entrance):
        if fault["fired"] or fault["operation_id"] is None:
            return
        record = objects[id(conn)][1]
        if record["database"] != fault["database"]:
            return
        table = ("visual_local_publications_v1" if fault["database"] == "event"
                 else "simulation_local_publications_v1")
        rows = [dict(row) for row in conn.execute(
            f"SELECT * FROM {table} WHERE operation_id=?", (fault["operation_id"],)
        )]
        if not any(row["phase"] == fault["phase"] for row in rows):
            return
        assert conn.in_transaction is False
        fault["fired"] = True
        evidence = {
            "kind": "TRUE_COMMIT_THEN_SAME_CONNECTION_CLOSE", "entrance": entrance,
            "resource_id": id(conn), "database_path": record["path"],
            "operation_id": fault["operation_id"], "phase": fault["phase"], "durable_rows": rows,
            "thread": threading.get_ident(), "native_thread": threading.get_native_id(),
            "in_transaction_after_commit": conn.in_transaction,
        }
        value["observations"]["scenarios"].append(evidence)
        conn.close()
        try:
            conn.execute("SELECT 1")
        except sqlite3.ProgrammingError as error:
            evidence["actual_closed_connection_error"] = {
                "type": type(error).__name__, "message": str(error),
            }
            raise
        raise AssertionError("closed SQLite connection unexpectedly executed SQL")

    class _b_t2_Connection(sqlite3.Connection):
        def __init__(self, database, *args, **kwargs):
            path = str(Path(database).resolve())
            record = add(self, "sqlite_connection", path=path,
                         database="event" if Path(path).name == "events.db" else "job")
            try:
                super().__init__(database, *args, **kwargs)
            except BaseException as error:
                record["initialization_error"] = {"type": type(error).__name__, "message": str(error)}
                raise
            record["initialized"] = True

        def execute(self, sql, parameters=(), /):
            result = super().execute(sql, parameters)
            if sql.strip().rstrip(";").upper() in {"COMMIT", "END", "END TRANSACTION"}:
                after_commit(self, "execute")
            return result

        def commit(self):
            active = self.in_transaction
            result = super().commit()
            if active:
                after_commit(self, "commit")
            return result

        def __exit__(self, kind, error, traceback):
            active = self.in_transaction
            result = super().__exit__(kind, error, traceback)
            if kind is None and active:
                after_commit(self, "__exit__")
            return result

        def close(self):
            return close_wrapper(sqlite3.Connection.close, "sqlite_connection")(self)

    actual_connect = sqlite3.connect

    def connect(*args, **kwargs):
        assert "factory" not in kwargs, "T2 observer requires the actual default SQLite factory seam"
        return actual_connect(*args, factory=_b_t2_Connection, **kwargs)

    context = monkeypatch.context()
    patcher = context.__enter__()

    def patch(cls, name, replacement):
        key = (cls, name)
        if key not in methods:
            methods[key] = getattr(cls, name)
            patcher.setattr(cls, name, replacement)

    def clock_factory(destination):
        raw = _Counter()
        marker = SimpleNamespace()
        record = add(marker, "OC1_clock", domain_kind=destination)
        try:
            clock = _open_clock_for_test(raw)
        except BaseException as error:
            record["initialization_error"] = {"type": type(error).__name__, "message": str(error)}
            raise
        del objects[id(marker)]
        objects[id(clock)] = (clock, record)
        record.update(resource_id=id(clock), class_module=type(clock).__module__,
                      class_name=type(clock).__qualname__, initialized=True,
                      issuer_thread=threading.get_ident(), issuer_native_thread=threading.get_native_id())
        clocks.append((clock, raw, destination))
        if (type(clock), "close") not in methods:
            patch(type(clock), "close", close_wrapper(type(clock).close, "OC1_clock"))
        return clock

    session_code = lease_module.OperationalLeaseSession.__init__.__code__

    def profile(frame, event, arg):
        if frame.f_code is poll_code and event == "call":
            call = getattr(poll_context, "call", None)
            if call is not None and frame.f_locals.get("self") is objects[call["worker_resource_id"]][0]:
                call["entered"] = True
                call["entry_sequence"] = tick()
                call["thread_id"] = threading.get_ident()
                call["native_thread_id"] = threading.get_native_id()
        for worker in tuple(worker_refs):
            sample_runtime(worker)
        if frame.f_code is session_code and event == "call":
            session = frame.f_locals["self"]
            add(session, "lease_session")
            session_refs.append(session)
        elif frame.f_code is session_code and event == "return":
            session = frame.f_locals["self"]
            record = objects[id(session)][1]
            record["initialized"] = getattr(session, "_sealed", False) is True
            if not record["initialized"]:
                record["initialization_error"] = {"type": "IncompleteConstructor",
                                                  "message": "actual session constructor did not seal"}
        callback = state.wait_observer
        if callback is not None:
            callback(frame, event, arg)

    state = SimpleNamespace(value=value, fault=fault, clocks=clocks, objects=objects,
                            release_events=release_events, workers=worker_refs, sessions=session_refs,
                            wait_observer=None, add=add)
    try:
        patcher.setattr(sqlite3, "connect", connect)
        for cls, kind in (
            (InMemoryEventAutonomyRepository, "memory_repository"),
            (SQLiteEventAutonomyRepository, "event_repository"),
            (SQLiteSimulationJobRepository, "job_repository"),
            (SimulationWorker, "worker"),
        ):
            patch(cls, "__init__", init_wrapper(cls.__init__, kind))
        patch(SimulationWorker, "poll_once", poll_once)
        for cls, kind in ((InMemoryEventAutonomyRepository, "memory_repository"),
                          (SQLiteEventAutonomyRepository, "event_repository")):
            patch(cls, "close", close_wrapper(cls.close, kind))
        patcher.setattr(lease_module, "open_operational_clock", lambda: clock_factory("D_lease"))
        patcher.setattr(operational_windows, "open_operational_clock", lambda: clock_factory("D_app"))
        sys.setprofile(profile)
        threading.setprofile(profile)
        yield state
    finally:
        state.wait_observer = None
        for released in release_events:
            released.set()
        for session in session_refs:
            try:
                if not getattr(session, "_closed", False):
                    lease_module._close_worker_lease_session(session, reason="T2-finally")
                record = objects[id(session)][1]
                broker = getattr(session, "_broker", None)
                record["broker_alive"] = None if broker is None else broker.is_alive()
                record["cleanup_observed"] = (
                    getattr(session, "_closed", False) is True and broker is not None and not broker.is_alive()
                )
            except BaseException as error:
                value["cleanup_errors"].append({"resource_id": id(session),
                    "type": type(error).__name__, "message": str(error)})
        for clock, _, _ in clocks:
            if (not clock._closed
                    and objects[id(clock)][1]["issuer_thread"] == threading.get_ident()):
                try:
                    clock.close()
                except BaseException as error:
                    value["cleanup_errors"].append({"resource_id": id(clock),
                        "type": type(error).__name__, "message": str(error)})
        for obj, record in list(objects.values()):
            try:
                kind = record["kind"]
                if kind in {"memory_repository", "event_repository", "sqlite_connection"}:
                    if record["initialized"] and record["cleanup_observed"] is not True:
                        obj.close()
                elif kind == "OC1_clock":
                    record["cleanup_observed"] = obj._closed is True
                elif kind == "job_repository":
                    record["TLS_connection"] = getattr(obj._transactions, "connection", None) is not None
                    owned = [row for _, row in objects.values()
                             if row["kind"] == "sqlite_connection"
                             and row.get("path") == str(obj.database_path.resolve())]
                    record["cleanup_observed"] = not record["TLS_connection"] and all(
                        row["cleanup_observed"] is True for row in owned)
                elif kind == "worker":
                    sample_runtime(obj)
                    session = getattr(obj, "_operational_lease_session", None)
                    heartbeat = None if session is None else getattr(session, "_heartbeat_thread", None)
                    record["heartbeat_alive"] = None if heartbeat is None else heartbeat.is_alive()
                    record["final_active_job_id"] = getattr(obj, "active_job_id", None)
                    calls = [call for call in value["worker_lifecycles"]
                             if call["worker_resource_id"] == id(obj)]
                    if not calls:
                        record["cleanup_basis"] = "never_polled_no_owned_runtime"
                        record["cleanup_observed"] = (
                            record["initial_active_job_id"] == ""
                            and record["final_active_job_id"] == ""
                            and record["session_observed"] is False
                            and record["heartbeat_observed"] is False
                            and session is None and heartbeat is None
                            and not record["close_attempts"])
                    else:
                        record["cleanup_basis"] = "poll_finished_runtime_released"
                        sessions = [objects[item][0] for item in record["session_resource_ids"]]
                        threads = [objects[item][0] for item in
                                   record["broker_resource_ids"] + record["heartbeat_resource_ids"]]
                        record["cleanup_observed"] = (
                            all(call["end_sequence"] is not None for call in calls)
                            and record["final_active_job_id"] == ""
                            and record["session_observed"] is not None
                            and record["heartbeat_observed"] is not None
                            and all(getattr(item, "_closed", False) is True for item in sessions)
                            and all(not item.is_alive() for item in threads)
                            and (session is None or getattr(session, "_closed", False) is True)
                            and (heartbeat is None or not heartbeat.is_alive()))
                elif kind in {"helper_thread", "broker_thread", "heartbeat_thread"}:
                    if obj.ident is not None and obj is not threading.current_thread():
                        obj.join(timeout=2)
                    record["thread_ident"] = obj.ident
                    record["native_thread_id"] = obj.native_id
                    record["alive_after_join"] = obj.is_alive()
                    record["cleanup_observed"] = not obj.is_alive()
            except BaseException as error:
                value["cleanup_errors"].append({"resource_id": record["resource_id"],
                    "type": type(error).__name__, "message": str(error)})
        sys.setprofile(previous_profile)
        threading.setprofile(previous_thread_profile)
        context.__exit__(None, None, None)
        restored = all(getattr(cls, name) is original for (cls, name), original in methods.items())
        value["observations"]["observers_restored"] = (
            restored and sys.getprofile() is previous_profile
            and threading.getprofile() is previous_thread_profile and sqlite3.connect is actual_connect)
        value["observations"]["method_restoration"] = restored
        value["allocation_attempts"] = len(value["resources"])
        objects.clear()
